<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Collective;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\Storage;class CollectiveController extends Controller{public function index(){return view('admin.collectives.index',['items'=>Collective::orderBy('sort')->get()]);}public function create(){return view('admin.collectives.form',['item'=>new Collective]);}public function store(Request $r){Collective::create($this->data($r));return redirect()->route('admin.collectives.index')->with('ok','Коллектив добавлен');}public function edit(Collective $collective){return view('admin.collectives.form',['item'=>$collective]);}public function update(Request $r,Collective $collective){$old=$collective->image;$d=$this->data($r,$collective);$collective->update($d);if(isset($d['image'])&&$old&&$old!==$d['image'])Storage::disk('public')->delete($old);return redirect()->route('admin.collectives.index')->with('ok','Сохранено');}public function destroy(Collective $collective){if($collective->image)Storage::disk('public')->delete($collective->image);$collective->delete();return back()->with('ok','Коллектив удалён');}private function data(Request $r,?Collective $item=null){$d=$r->validate(['name'=>'required|max:255','leader'=>'nullable|max:255','description'=>'nullable','sort'=>'nullable|integer','image'=>'nullable|image|max:10240']);$base=Str::slug($r->input('slug')?:$d['name'])?:'collective';$slug=$base;$i=2;while(Collective::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('image'))$d['image']=$r->file('image')->store('collectives','public');$d['is_active']=$r->boolean('is_active');return $d;}}